  "title": "Mưa Đà Lạt, ấm trong nhà",
  "summary": "Trời mưa nên mình đổi hết sang chỗ có mái che, vẫn trọn một ngày Đà Lạt nhẹ nhàng từ chùa, dinh thự đến quán xá ấm cúng.",
  "stops": [
    {
      "poi_id": "p8",
      "kind": "activity",
      "must_do_id": null,
      "note": "Chùa có mái che, mưa vẫn thong thả ngắm khảm sành, không ướt lông."
    },
    {
      "poi_id": "p11",
      "kind": "activity",
      "must_do_id": null,
      "note": "Dinh III kín gió, vừa tránh mưa vừa xem đồ xưa, hợp người thích nhàn nhã."
    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Ngồi bàn ấm, nem nướng cuốn rau thơm, mưa ngoài kia kệ mưa."
    },
    {
      "poi_id": "p23",
      "kind": "activity",
      "must_do_id": null,
      "note": "Bảo tàng trong nhà, trưa mưa vào đây chậm rãi xem lịch sử địa phương."
    },
    {
      "poi_id": "p144",
      "kind": "activity",
      "must_do_id": null,
      "note": "Tối đến khu phức hợp có mái che, ăn chơi nhẹ nhàng, khỏi ướt giày đỏ."
    },
    {
      "poi_id": "p330",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bistro ấm cúng, cà phê và món ngon, kết ngày mưa thật dịu."
    }
  ]
}
